ee:variables.ee:set-variable:
%dw 2.0
output application/java
---
(
  if (error.errorType.namespace == "HTTP" and error.errorType.identifier == "CONNECTIVITY")
    "Failed due to a CONNECTIVITY issue with the CMD API while connecting to the resource on "
  else if (error.errorType.namespace == "HTTP" and error.errorType.identifier == "UNAUTHORIZED")
    "Failed due to an UNAUTHORIZED (401) error with the CMD API while connecting to the resource on "
  else
    "Data sync from Salesforce to CMD failed due to an unexpected system error on "
) ++ now() as String { format: "yyyy-MM-dd" }
